/**
 * Weekly newsletter content — AI 整理的 ESG / SDG 重點 附 Brand Capital 解讀
 *
 * Each entry is one weekly issue. To add a new issue, append to NEWS_ENTRIES
 * with a unique slug (use ISO date prefix, e.g. "2026-w22-..."), set
 * `publishedAt` and `sections`, and commit. The list page and detail page
 * pick it up automatically.
 *
 * Future: this file can be generated by an automation that pulls from Notion
 * (docs/notion-sync) and re-commits weekly. Keep the schema stable for that.
 */

export type NewsCategory = "ESG" | "SDG" | "AI 治理" | "品牌資本";

export interface NewsSection {
  /** Section heading shown on the article page. */
  heading: string;
  /** 1-3 short paragraphs. Plain text; no HTML. */
  body: string[];
  /** Optional source links — title + URL. Shown as footnotes. */
  sources?: { title: string; url: string }[];
}

export interface NewsEntry {
  /** URL slug, must be unique. ISO-week prefix recommended. */
  slug: string;
  /** ISO date, e.g. "2026-05-27". */
  publishedAt: string;
  /** Display title. */
  title: string;
  /** 1-2 sentence summary shown on list view + meta description. */
  summary: string;
  /** Category badges, first one is primary. */
  categories: NewsCategory[];
  /** The article body, structured into sections. */
  sections: NewsSection[];
  /** Brand Capital 解讀 — Symcio 的觀點段落,獨立於正文。 */
  brandCapitalTake: string[];
}

