export function findEntry(slug: string): NewsEntry | undefined {
  return NEWS_ENTRIES.find((e) => e.slug === slug);
}

export function sortedEntries(): NewsEntry[] {
  return [...NEWS_ENTRIES].sort((a, b) =>
    a.publishedAt < b.publishedAt ? 1 : -1,
  );
}
